function se($v): string { return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8'); }
function srp($v): string { return 'Rp '.number_format((float)$v,0,',','.'); }
function shop_go(string $q=''): never { header('Location: store.php'.$q); exit; }
function shop_user(PDO $pdo): ?array {
 if (empty($_SESSION['auth']['id'])) return null;
 $s=$pdo->prepare("SELECT u.id_user,u.nama,u.username,m.id_pelanggan,p.kota FROM tbl_user u JOIN tbl_akun_pelanggan m ON m.id_user=u.id_user JOIN tbl_pelanggan p ON p.id_pelanggan=m.id_pelanggan WHERE u.id_user=? AND u.role='user'");
 $s->execute([(int)$_SESSION['auth']['id']]); return $s->fetch() ?: null;
}
function shop_image(string $path): string { return $path && is_file(__DIR__.'/'.$path) ? $path : ''; }
$action=$_POST['action']??'';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 try {
  if ($action==='register') {
   $nama=trim((string)($_POST['nama']??'')); $username=strtolower(trim((string)($_POST['username']??''))); $pass=(string)($_POST['password']??''); $kota=trim((string)($_POST['kota']??''));
