   $pdo->prepare("INSERT INTO tbl_user(nama,username,password,role) VALUES(?,?,?,'user')")->execute([$nama,$username,password_hash($pass,PASSWORD_DEFAULT)]); $idu=(int)$pdo->lastInsertId();
   $pdo->prepare('INSERT INTO tbl_akun_pelanggan(id_user,id_pelanggan) VALUES(?,?)')->execute([$idu,$idp]); $pdo->commit();
   session_regenerate_id(true);$_SESSION['auth']=['id'=>$idu,'nama'=>$nama,'role'=>'user'];shop_go('?sukses=daftar');
  }
  if ($action==='login') {
