  if ($action==='add') {
   $id=(int)($_POST['id_produk']??0);$qty=max(1,min(99,(int)($_POST['jumlah']??1)));$s=$pdo->prepare('SELECT stok FROM tbl_produk WHERE id_produk=?');$s->execute([$id]);$stock=$s->fetchColumn();if($stock===false||(int)$stock<1)throw new RuntimeException('Produk sedang habis.');
   
   $current=(int)($_SESSION['shop_cart'][$id]??0);
