   $_SESSION['shop_cart'][$id]=$current+$qty;$_SESSION['shop_added']='Produk berhasil ditambahkan ke keranjang.';shop_go();
  }
  if ($action==='update') { foreach(($_POST['qty']??[]) as $id=>$q){$id=(int)$id;$q=max(0,(int)$q);if($q===0){unset($_SESSION['shop_cart'][$id]);continue;}$st=$pdo->prepare('SELECT stok FROM tbl_produk WHERE id_produk=?');$st->execute([$id]);$stock=$st->fetchColumn();if($stock===false){unset($_SESSION['shop_cart'][$id]);continue;}if($q>(int)$stock)throw new RuntimeException('Jumlah melebihi stok tersedia untuk produk ID '.$id.'.');$_SESSION['shop_cart'][$id]=min(99,$q);}shop_go('?cart=1'); }
