   $dir=__DIR__.'/assets/uploads/bukti';if(!is_dir($dir))mkdir($dir,0775,true);$name=bin2hex(random_bytes(10)).'.'.$ext;if(!move_uploaded_file($_FILES['bukti']['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Gagal menyimpan bukti.');
