 } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack();$_SESSION['shop_error']=$e->getMessage();shop_go(isset($_POST['id_transaksi'])?'?order='.(int)$_POST['id_transaksi']:(isset($_POST['action'])&&in_array($_POST['action'],['login','register'])?'?account=1':'?cart=1')); }
