$cats=$pdo->query("SELECT DISTINCT kategori FROM tbl_produk WHERE kategori IS NOT NULL AND kategori<>'' ORDER BY kategori")->fetchAll(PDO::FETCH_COLUMN);$cat=trim((string)($_GET['kategori']??''));$search=trim((string)($_GET['q']??''));
if($search!=='')$products=array_values(array_filter($products,fn($p)=>mb_stripos($p['nama_produk'],$search)!==false||mb_stripos((string)$p['deskripsi'],$search)!==false));if($cat!=='')$products=array_values(array_filter($products,fn($p)=>$p['kategori']===$cat));
